import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("a single sword → base premium 100 G");
    it.todo("a single amulet → base premium 60 G");
    it.todo("a single staff → base premium 80 G");
    it.todo("a single potion → base premium 40 G");
    it.todo("a single rune (component) → base premium 25 G");
    it.todo("a single moonstone (component) → base premium 25 G");
    it.todo("a sword and an amulet → policy base premium 160 G");
  });

  describe("quote — component blocks", () => {
    it.todo("2 runes → 50 G base premium");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — item-level modifiers", () => {
    it.todo("cursed sword → 50 % risk surcharge on the item's base premium");
    it.todo("sword with exactly enchantment 5 → 30 % high-enchantment surcharge applies");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("cursed sword with exactly enchantment 5 → both surcharges apply");
    it.todo(
      "cursed sword (100 G) plus plain amulet (60 G) → curse adds 50 G (50 % of the cursed item only), 210 G before further modifiers and fee",
    );
  });

  describe("quote — policy-level modifiers", () => {
    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
    it.todo("customer with 1 year with MHPCO → no loyalty discount");
    it.todo("first insurance → 10 % initial assessment surcharge on the policy base premium");
    it.todo("each contract after the first → 15 % follow-up discount");
    it.todo("the 5 G processing fee is added at the very end of every premium");
  });

  describe("quote — rounding in the MHPCO's favor", () => {
    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
  });

  describe("quote — integration examples", () => {
    it.todo("newcomer (0 years, no previous contract) with a cursed sword → premium 165 G");
    it.todo(
      "long-standing customer (3 years), second quote, cursed sword with enchantment 7 → premium 160 G",
    );
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G");
  });

  describe("claim — special clauses", () => {
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
    it.todo(
      "dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement then deductible)",
    );
    it.todo(
      "dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins)",
    );
    it.todo(
      "dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G (threshold is ≥ 8)",
    );
  });

  describe("claim — deductible per damage event", () => {
    it.todo(
      "a dragon attack damages an insured sword (500 G) and an insured amulet (300 G) → payout 600 G (deductible once per damaged item)",
    );
  });

  describe("claim — rounding in the MHPCO's favor", () => {
    it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  });

  describe("claim — cap", () => {
    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
    it.todo(
      "a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)",
    );
    it.todo(
      "a policy covering a sword and 3 runes (a block) → insurance sum 1750 G (block discount affects the premium only)",
    );
    it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
    it.todo(
      "sword policy, second successive claim of 1500 G → payout 600 G, remainingCap 0 G (reduced to the remaining cap)",
    );
  });

  describe("claim — multiple items of the same type", () => {
    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
    it.todo(
      "two sword damage entries against a policy with two swords → each is a separate damage with its own deductible",
    );
    it.todo(
      "more damage entries of a type than the policy covers (two sword damages, one sword insured) → error",
    );
  });

  describe("error cases", () => {
    it.todo("quote includes an item with an unknown type (broomstick) → error");
    it.todo("claim damages an amulet when only a sword is insured → error");
    it.todo("claim references a damage entry with an unknown item type → error");
    it.todo("claim contains a damage entry with amount -200 → error");
  });

  describe("scenario processing", () => {
    it.todo("results array has the same length and order as the input steps");
    it.todo(
      "a claim step refers to the policy created by an earlier quote step via its zero-based step index",
    );
  });

  describe("CLI", () => {
    it.todo("reads a JSON scenario from stdin and writes the results JSON to stdout");
    it.todo(
      "on an invalid scenario exits with a non-zero status code, writes to stderr, and writes no results to stdout",
    );
  });
});

