export type Item = {
  type: string;
};

export type QuoteStep = {
  op: "quote";
  items: Item[];
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};

export type ScenarioResults = {
  results: unknown[];
};

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
};

const quote = (step: QuoteStep): { premium: number } => {
  const basePremium = step.items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

  return {
    premium: basePremium + basePremium * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE,
  };
};

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map(quote),
});

