export type Item = {
  type: string;
};

export type QuoteStep = {
  op: "quote";
  items: Item[];
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};

export type ScenarioResults = {
  results: unknown[];
};

const PROCESSING_FEE = 5;
const INITIAL_ASSESSMENT_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const policyBasePremium = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

/** Premiums are rounded in the MHPCO's favour, i.e. up. */
const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

/**
 * Applies a surcharge additively rather than as `amount * (1 + rate)`.
 * The multiplicative form introduces IEEE-754 error that `roundInMHPCOsFavour`
 * then amplifies to a whole Gold piece — e.g. `100 * 1.1` is 110.00000000000001,
 * which rounds up to 116 instead of the specified 115. Do not "simplify" this.
 */
const withSurcharge = (amount: number, rate: number): number => amount + amount * rate;

const quote = (step: QuoteStep): { premium: number } => {
  const assessedPremium = withSurcharge(
    policyBasePremium(step.items),
    INITIAL_ASSESSMENT_SURCHARGE,
  );

  return { premium: roundInMHPCOsFavour(assessedPremium + PROCESSING_FEE) };
};

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map(quote),
});

