  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const DEDUCTIBLE = 100;
const CAP_MULTIPLE = 2;

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

