  const assessedPremium = withSurcharge(basePremium, INITIAL_ASSESSMENT_SURCHARGE);
  const itemSurcharges = policyItemSurchargeTotal(step.items);
  const policyModifiers = policyModifierTotal(basePremium, state);

  return {
    premium: roundPremiumInMHPCOsFavour(
      assessedPremium + itemSurcharges + policyModifiers + PROCESSING_FEE,
    ),
  };
};

/** The payout half of the rule on `roundPremiumInMHPCOsFavour`: down. */
const roundPayoutInMHPCOsFavour = (payout: number): number => Math.floor(payout);

const insuranceSum = (items: Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);

/**
 * Damage to a highly enchanted item is only half reimbursed. The clause applies
 * to the damage amount; the deductible is subtracted afterwards.
 */
const reimbursement = (item: Item, amount: number): number =>
  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_LEVEL ? amount * HALF_REIMBURSEMENT : amount;

/** A deductible applies per damage event, i.e. once per damaged item. */
const damagePayout = (damage: Damage, policy: Policy): number => {
  const item = policy.items.find(({ type }) => type === damage.itemType) as Item;

  return reimbursement(item, damage.amount) - DEDUCTIBLE;
};

/**
 * A claim names the policy it is made against by the step index of the quote
 * that created it. That the policy exists is currently an *assumption*, not a
 * guarantee — a claim naming an unissued policy is a specified error case that
 * is not implemented yet, so this deliberately still fails on `undefined`.
 * The assumption is named here so that the missing check is visible rather
 * than buried in an `as` cast.
 */
const assumeIssued = (policy: Policy | undefined): Policy => policy as Policy;

const claim = (
  step: ClaimStep,
  state: ScenarioState,
): { payout: number; remainingCap: number } => {
  const policy = assumeIssued(state.policies.get(step.policy));
  const cap = CAP_MULTIPLE * insuranceSum(policy.items);
  const payout = roundPayoutInMHPCOsFavour(
    step.incident.damages.reduce((sum, damage) => sum + damagePayout(damage), 0),
  );

  return { payout, remainingCap: cap - payout };
};

/**
 * Steps are processed in order and later steps depend on earlier ones — a quote
 * issues a contract that discounts every following quote, and a claim is made
 * against a policy an earlier quote created. Each step therefore maps its
 * incoming state to a result plus the state the next step sees.
 */
const runStep = (
  step: Step,
  state: ScenarioState,
  index: number,
): { result: unknown; nextState: ScenarioState } =>
  step.op === "quote"
    ? {
        result: quote(step, state),
        nextState: {
          ...state,
          contractsIssued: state.contractsIssued + 1,
          policies: new Map(state.policies).set(index, { items: step.items }),
        },
      }
    : { result: claim(step, state), nextState: state };

export const runScenario = (scenario: Scenario): ScenarioResults => {
  const { results } = scenario.steps.reduce<{
    results: unknown[];
    state: ScenarioState;
  }>(
    ({ results, state }, step, index) => {
      const { result, nextState } = runStep(step, state, index);

      return { results: [...results, result], state: nextState };
    },
    {
      results: [],
      state: { customer: scenario.customer, contractsIssued: 0, policies: new Map() },
    },
  );

  return { results };
};

